package misc

import (
	"errors"
	"fmt"

	"github.com/holiman/uint256"

	"github.com/erigontech/erigon-lib/common"
	"github.com/erigontech/erigon-lib/log/v3"
	"github.com/erigontech/erigon/execution/abi"
	"github.com/erigontech/erigon/execution/types"
)

const (
	BLSPubKeyLen             = 48
	WithdrawalCredentialsLen = 32 // withdrawalCredentials size
	BLSSigLen                = 96 // signature size
	DepositLogLen            = 576
)

var depositTopic = common.HexToHash("0x649bbc62d0e31342afea4e5cd82d4049e7e1ee912fc0889aa790803be39038c5")

var (
	// DepositABI is an ABI instance of beacon chain deposit events.
	DepositABI   = abi.ABI{Events: map[string]abi.Event{"DepositEvent": depositEvent}}
	bytesT, _    = abi.NewType("bytes", "", nil)
	depositEvent = abi.NewEvent("DepositEvent", "DepositEvent", false, abi.Arguments{
		{Name: "pubkey", Type: bytesT, Indexed: false},
		{Name: "withdrawal_credentials", Type: bytesT, Indexed: false},
		{Name: "amount", Type: bytesT, Indexed: false},
		{Name: "signature", Type: bytesT, Indexed: false},
		{Name: "index", Type: bytesT, Indexed: false}},
	)
)

// field type overrides for abi upacking
type depositUnpacking struct {
	Pubkey                []byte
	WithdrawalCredentials []byte
	Amount                []byte
	Signature             []byte
	Index                 []byte
}

var InvalidDepositLogErr = errors.New("invalid deposit log: unsupported data layout")

func validateDepositLog(data []byte) error {
	if len(data) != DepositLogLen {
		return InvalidDepositLogErr
	}
	pubkeyOffset := uint256.NewInt(0).SetBytes(data[0:32])
	withdrawalCredentialsOffset := uint256.NewInt(0).SetBytes(data[32:64])
	amountOffset := uint256.NewInt(0).SetBytes(data[64:96])
	signatureOffset := uint256.NewInt(0).SetBytes(data[96:128])
	indexOffset := uint256.NewInt(0).SetBytes(data[128:160])

	if pubkeyOffset.CmpUint64(160) != 0 ||
		withdrawalCredentialsOffset.CmpUint64(256) != 0 ||
		amountOffset.CmpUint64(320) != 0 ||
		signatureOffset.CmpUint64(384) != 0 ||
		indexOffset.CmpUint64(512) != 0 {
		return InvalidDepositLogErr
	}

	pubkeySize := uint256.NewInt(0).SetBytes(data[160:192])
	withdrawalCredentialsSize := uint256.NewInt(0).SetBytes(data[256:288])
	amountSize := uint256.NewInt(0).SetBytes(data[320:352])
	signatureSize := uint256.NewInt(0).SetBytes(data[384:416])
	indexSize := uint256.NewInt(0).SetBytes(data[512:544])

	if pubkeySize.CmpUint64(BLSPubKeyLen) != 0 ||
		withdrawalCredentialsSize.CmpUint64(WithdrawalCredentialsLen) != 0 ||
		amountSize.CmpUint64(8) != 0 ||
		signatureSize.CmpUint64(BLSSigLen) != 0 ||
		indexSize.CmpUint64(8) != 0 {
		return InvalidDepositLogErr
	}
	return nil
}

// unpackDepositLog unpacks a serialized DepositEvent.
func unpackDepositLog(data []byte) ([]byte, error) {
	var du depositUnpacking
	if err := validateDepositLog(data); err != nil {
		return nil, err
	}
	if err := DepositABI.UnpackIntoInterface(&du, "DepositEvent", data); err != nil {
		return nil, err
	}
	reqData := make([]byte, 0, types.DepositRequestDataLen)
	reqData = append(reqData, du.Pubkey...)
	reqData = append(reqData, du.WithdrawalCredentials...)
	reqData = append(reqData, du.Amount...)
	reqData = append(reqData, du.Signature...)
	reqData = append(reqData, du.Index...)

	return reqData, nil
}

// ParseDepositLogs extracts the EIP-6110 deposit values from logs emitted by
// BeaconDepositContract and returns a FlatRequest object ptr
func ParseDepositLogs(logs []*types.Log, depositContractAddress common.Address) (*types.FlatRequest, error) {
	if depositContractAddress == (common.Address{}) {
		log.Warn("Error in ParseDepositLogs - depositContractAddress is 0x0")
	}
	reqData := make([]byte, 0, len(logs)*types.DepositRequestDataLen)
	for _, l := range logs {
		if l.Address == depositContractAddress && len(l.Topics) > 0 && l.Topics[0] == depositTopic {
			d, err := unpackDepositLog(l.Data)
			if err != nil {
				return nil, fmt.Errorf("unable to parse deposit data: %v", err)
			}
			reqData = append(reqData, d...)
		}
	}
	if len(reqData) > 0 {
		return &types.FlatRequest{Type: types.DepositRequestType, RequestData: reqData}, nil
	}
	return nil, nil
}

package cltypes

import (
	"crypto/sha256"
	"encoding/json"

	"github.com/erigontech/erigon-lib/common"
	"github.com/erigontech/erigon-lib/common/hexutil"
	"github.com/erigontech/erigon-lib/types/clonable"
	"github.com/erigontech/erigon/cl/clparams"
	"github.com/erigontech/erigon/cl/cltypes/solid"
	"github.com/erigontech/erigon/cl/merkle_tree"
	ssz2 "github.com/erigontech/erigon/cl/ssz"
)

var (
	_ solid.EncodableHashableSSZ = (*ExecutionRequests)(nil)
	_ ssz2.SizedObjectSSZ        = (*ExecutionRequests)(nil)
)

// class ExecutionRequests(Container):
//
//	deposits: List[DepositRequest, MAX_DEPOSIT_REQUESTS_PER_PAYLOAD]  # [New in Electra:EIP6110]
//	withdrawals: List[WithdrawalRequest, MAX_WITHDRAWAL_REQUESTS_PER_PAYLOAD]  # [New in Electra:EIP7002:EIP7251]
//	consolidations: List[ConsolidationRequest, MAX_CONSOLIDATION_REQUESTS_PER_PAYLOAD]  # [New in Electra:EIP7251]
type ExecutionRequests struct {
	Deposits       *solid.ListSSZ[*solid.DepositRequest]       `json:"deposits"`
	Withdrawals    *solid.ListSSZ[*solid.WithdrawalRequest]    `json:"withdrawals"`
	Consolidations *solid.ListSSZ[*solid.ConsolidationRequest] `json:"consolidations"`

	cfg *clparams.BeaconChainConfig
}

func NewExecutionRequests(cfg *clparams.BeaconChainConfig) *ExecutionRequests {
	return &ExecutionRequests{
		Deposits:       solid.NewStaticListSSZ[*solid.DepositRequest](int(cfg.MaxDepositRequestsPerPayload), solid.SizeDepositRequest),
		Withdrawals:    solid.NewStaticListSSZ[*solid.WithdrawalRequest](int(cfg.MaxWithdrawalRequestsPerPayload), solid.SizeWithdrawalRequest),
		Consolidations: solid.NewStaticListSSZ[*solid.ConsolidationRequest](int(cfg.MaxConsolidationRequestsPerPayload), solid.SizeConsolidationRequest),
		cfg:            cfg,
	}
}

func (e *ExecutionRequests) EncodingSizeSSZ() int {
	return e.Deposits.EncodingSizeSSZ() + e.Withdrawals.EncodingSizeSSZ() + e.Consolidations.EncodingSizeSSZ()
}

func (e *ExecutionRequests) EncodeSSZ(buf []byte) ([]byte, error) {
	return ssz2.MarshalSSZ(buf, e.Deposits, e.Withdrawals, e.Consolidations)
}

func (e *ExecutionRequests) DecodeSSZ(buf []byte, version int) error {
	return ssz2.UnmarshalSSZ(buf, version, e.Deposits, e.Withdrawals, e.Consolidations)
}

func (e *ExecutionRequests) Clone() clonable.Clonable {
	return NewExecutionRequests(e.cfg)
}

func (e *ExecutionRequests) HashSSZ() ([32]byte, error) {
	return merkle_tree.HashTreeRoot(e.Deposits, e.Withdrawals, e.Consolidations)
}

func (e *ExecutionRequests) Static() bool {
	return false
}

func (e *ExecutionRequests) UnmarshalJSON(b []byte) error {
	c := struct {
		Deposits       *solid.ListSSZ[*solid.DepositRequest]       `json:"deposits"`
		Withdrawals    *solid.ListSSZ[*solid.WithdrawalRequest]    `json:"withdrawals"`
		Consolidations *solid.ListSSZ[*solid.ConsolidationRequest] `json:"consolidations"`
	}{
		Deposits:       solid.NewStaticListSSZ[*solid.DepositRequest](int(e.cfg.MaxDepositRequestsPerPayload), solid.SizeDepositRequest),
		Withdrawals:    solid.NewStaticListSSZ[*solid.WithdrawalRequest](int(e.cfg.MaxWithdrawalRequestsPerPayload), solid.SizeWithdrawalRequest),
		Consolidations: solid.NewStaticListSSZ[*solid.ConsolidationRequest](int(e.cfg.MaxConsolidationRequestsPerPayload), solid.SizeConsolidationRequest),
	}
	if err := json.Unmarshal(b, &c); err != nil {
		return err
	}

	e.Deposits = c.Deposits
	e.Withdrawals = c.Withdrawals
	e.Consolidations = c.Consolidations
	return nil
}

func ComputeExecutionRequestHash(executionRequests []hexutil.Bytes) common.Hash {
	sha := sha256.New()
	for _, r := range executionRequests {
		hi := sha256.Sum256(r)
		sha.Write(hi[:])
	}
	h := common.BytesToHash(sha.Sum(nil))
	return h
}

