    36→type SetCodeTransaction struct {
    37→	DynamicFeeTransaction
    38→	Authorizations []Authorization
    39→}
    40→
    41→func (tx *SetCodeTransaction) Unwrap() Transaction {
    42→	return tx
    43→}
    44→
    45→func (tx *SetCodeTransaction) Type() byte {
    46→	return SetCodeTxType
    47→}
    48→
    49→func (tx *SetCodeTransaction) GetBlobHashes() []common.Hash {
    50→	return []common.Hash{}
    51→}
    52→
    53→func (tx *SetCodeTransaction) GetAuthorizations() []Authorization {
    54→	return tx.Authorizations
    55→}
    56→
    57→func (tx *SetCodeTransaction) copy() *SetCodeTransaction {
    58→	cpy := &SetCodeTransaction{}
    59→	cpy.DynamicFeeTransaction = *tx.DynamicFeeTransaction.copy()
    60→
    61→	cpy.Authorizations = make([]Authorization, len(tx.Authorizations))
    62→
    63→	for i, ath := range tx.Authorizations {
    64→		cpy.Authorizations[i] = *ath.copy()
    65→	}
    66→
    67→	return cpy
    68→}
    69→
    70→func (tx *SetCodeTransaction) EncodingSize() int {
    71→	payloadSize, _, _, _, _ := tx.payloadSize()
    72→	// Add envelope size and type size
    73→	return 1 + rlp.ListPrefixLen(payloadSize) + payloadSize
    74→}
    75→
    76→func (tx *SetCodeTransaction) payloadSize() (payloadSize, nonceLen, gasLen, accessListLen, authorizationsLen int) {
    77→	payloadSize, nonceLen, gasLen, accessListLen = tx.DynamicFeeTransaction.payloadSize()
    78→	// size of Authorizations
    79→	authorizationsLen = authorizationsSize(tx.Authorizations)
    80→	payloadSize += rlp.ListPrefixLen(authorizationsLen) + authorizationsLen
    81→
    82→	return
    83→}
    84→
    85→func (tx *SetCodeTransaction) WithSignature(signer Signer, sig []byte) (Transaction, error) {
    86→	cpy := tx.copy()
    87→	r, s, v, err := signer.SignatureValues(tx, sig)
    88→	if err != nil {
    89→		return nil, err
    90→	}
    91→
    92→	cpy.R.Set(r)
    93→	cpy.S.Set(s)
    94→	cpy.V.Set(v)
    95→	cpy.ChainID = signer.ChainID()
    96→	return cpy, nil
    97→}
    98→
    99→func (tx *SetCodeTransaction) MarshalBinary(w io.Writer) error {
   100→	if tx.To == nil {
   101→		return ErrNilToFieldTx
   102→	}
   103→	payloadSize, nonceLen, gasLen, accessListLen, authorizationsLen := tx.payloadSize()
   104→	b := newEncodingBuf()
   105→	defer pooledBuf.Put(b)
   106→	// encode TxType
   107→	b[0] = SetCodeTxType
   108→	if _, err := w.Write(b[:1]); err != nil {
   109→		return err
   110→	}
   111→	if err := tx.encodePayload(w, b[:], payloadSize, nonceLen, gasLen, accessListLen, authorizationsLen); err != nil {
   112→		return err
   113→	}
   114→	return nil
   115→}
   116→
   117→func (tx *SetCodeTransaction) AsMessage(s Signer, baseFee *big.Int, rules *chain.Rules) (*Message, error) {
   118→	msg := Message{
   119→		nonce:      tx.Nonce,
   120→		gasLimit:   tx.GasLimit,
   121→		gasPrice:   *tx.FeeCap,
   122→		tipCap:     *tx.TipCap,
   123→		feeCap:     *tx.FeeCap,
   124→		to:         tx.To,
   125→		amount:     *tx.Value,
   126→		data:       tx.Data,
   127→		accessList: tx.AccessList,
   128→		checkNonce: true,
   129→	}
   130→	if !rules.IsPrague {
   131→		return nil, errors.New("SetCodeTransaction is only supported in Prague")
   132→	}
   133→	if baseFee != nil {
   134→		overflow := msg.gasPrice.SetFromBig(baseFee)
   135→		if overflow {
   136→			return nil, errors.New("gasPrice higher than 2^256-1")
   137→		}
   138→	}
   139→	msg.gasPrice.Add(&msg.gasPrice, tx.TipCap)
   140→	if msg.gasPrice.Gt(tx.FeeCap) {
   141→		msg.gasPrice.Set(tx.FeeCap)
   142→	}
   143→
   144→	if len(tx.Authorizations) == 0 {
   145→		return nil, errors.New("SetCodeTransaction without authorizations is invalid")
   146→	}
   147→	msg.authorizations = tx.Authorizations
   148→
   149→	var err error
   150→	msg.from, err = tx.Sender(s)
   151→	return &msg, err
   152→}
   153→
   154→func (tx *SetCodeTransaction) Sender(signer Signer) (common.Address, error) {
   155→	if from := tx.from.Load(); from != nil {
   156→		if *from != zeroAddr { // Sender address can never be zero in a transaction with a valid signer
   157→			return *from, nil
   158→		}
   159→	}
   160→	addr, err := signer.Sender(tx)
   161→	if err != nil {
   162→		return common.Address{}, err
   163→	}
   164→	tx.from.Store(&addr)
   165→	return addr, nil
   166→}
   167→
   168→func (tx *SetCodeTransaction) Hash() common.Hash {
   169→	if hash := tx.hash.Load(); hash != nil {
   170→		return *hash
   171→	}
   172→	hash := prefixedRlpHash(SetCodeTxType, []interface{}{
   173→		tx.ChainID,
   174→		tx.Nonce,
   175→		tx.TipCap,
   176→		tx.FeeCap,
   177→		tx.GasLimit,
   178→		tx.To,
   179→		tx.Value,
   180→		tx.Data,
   181→		tx.AccessList,
   182→		tx.Authorizations,
   183→		tx.V, tx.R, tx.S,
   184→	})
   185→	tx.hash.Store(&hash)
   186→	return hash
   187→}
   188→
   189→func (tx *SetCodeTransaction) SigningHash(chainID *big.Int) common.Hash {
   190→	return prefixedRlpHash(
   191→		SetCodeTxType,
   192→		[]interface{}{
   193→			chainID,
   194→			tx.Nonce,
   195→			tx.TipCap,
   196→			tx.FeeCap,
   197→			tx.GasLimit,
   198→			tx.To,
   199→			tx.Value,
   200→			tx.Data,
   201→			tx.AccessList,
   202→			tx.Authorizations,
   203→		})
   204→}
   205→
   206→func (tx *SetCodeTransaction) EncodeRLP(w io.Writer) error {
   207→	if tx.To == nil {
   208→		return ErrNilToFieldTx
   209→	}
   210→	payloadSize, nonceLen, gasLen, accessListLen, authorizationsLen := tx.payloadSize()
   211→	envelopSize := 1 + rlp.ListPrefixLen(payloadSize) + payloadSize
   212→	b := newEncodingBuf()
   213→	defer pooledBuf.Put(b)
   214→	// encode envelope size
   215→	if err := rlp.EncodeStringSizePrefix(envelopSize, w, b[:]); err != nil {
   216→		return err
   217→	}
   218→	// encode TxType
   219→	b[0] = SetCodeTxType
   220→	if _, err := w.Write(b[:1]); err != nil {
   221→		return err
   222→	}
   223→
   224→	return tx.encodePayload(w, b[:], payloadSize, nonceLen, gasLen, accessListLen, authorizationsLen)
   225→}
   226→
   227→func (tx *SetCodeTransaction) DecodeRLP(s *rlp.Stream) error {
   228→	_, err := s.List()
   229→	if err != nil {
   230→		return err
   231→	}
   232→	var b []byte
   233→	if b, err = s.Uint256Bytes(); err != nil {
   234→		return err
   235→	}
   236→	tx.ChainID = new(uint256.Int).SetBytes(b)
   237→	if tx.Nonce, err = s.Uint(); err != nil {
   238→		return err
   239→	}
   240→	if b, err = s.Uint256Bytes(); err != nil {
   241→		return err
   242→	}
   243→	tx.TipCap = new(uint256.Int).SetBytes(b)
   244→	if b, err = s.Uint256Bytes(); err != nil {
   245→		return err
   246→	}
   247→	tx.FeeCap = new(uint256.Int).SetBytes(b)
   248→	if tx.GasLimit, err = s.Uint(); err != nil {
   249→		return err
   250→	}
   251→	if b, err = s.Bytes(); err != nil {
   252→		return err
   253→	}
   254→	if len(b) != 20 {
   255→		return fmt.Errorf("wrong size for To: %d", len(b))
   256→	}
   257→	tx.To = &common.Address{}
   258→	copy((*tx.To)[:], b)
   259→	if b, err = s.Uint256Bytes(); err != nil {
   260→		return err
   261→	}
   262→	tx.Value = new(uint256.Int).SetBytes(b)
   263→	if tx.Data, err = s.Bytes(); err != nil {
   264→		return err
   265→	}
   266→	// decode AccessList
   267→	tx.AccessList = AccessList{}
   268→	if err = decodeAccessList(&tx.AccessList, s); err != nil {
   269→		return err
   270→	}
   271→
   272→	// decode authorizations
   273→	tx.Authorizations = make([]Authorization, 0)
   274→	if err = decodeAuthorizations(&tx.Authorizations, s); err != nil {
   275→		return err
   276→	}
   277→
   278→	// decode V
   279→	if b, err = s.Uint256Bytes(); err != nil {
   280→		return err
   281→	}
   282→	tx.V.SetBytes(b)
   283→	if b, err = s.Uint256Bytes(); err != nil {
   284→		return err
   285→	}
   286→	tx.R.SetBytes(b)
   287→	if b, err = s.Uint256Bytes(); err != nil {
   288→		return err
   289→	}
   290→	tx.S.SetBytes(b)
   291→	return s.ListEnd()
   292→}
   293→
   294→func (tx *SetCodeTransaction) encodePayload(w io.Writer, b []byte, payloadSize, _, _, accessListLen, authorizationsLen int) error {
   295→	// prefix
   296→	if err := rlp.EncodeStructSizePrefix(payloadSize, w, b); err != nil {
   297→		return err
   298→	}
   299→	// encode ChainID
   300→	if err := rlp.EncodeUint256(tx.ChainID, w, b); err != nil {
   301→		return err
   302→	}
   303→	// encode Nonce
   304→	if err := rlp.EncodeInt(tx.Nonce, w, b); err != nil {
   305→		return err
   306→	}
   307→	// encode MaxPriorityFeePerGas
   308→	if err := rlp.EncodeUint256(tx.TipCap, w, b); err != nil {
   309→		return err
   310→	}
   311→	// encode MaxFeePerGas
   312→	if err := rlp.EncodeUint256(tx.FeeCap, w, b); err != nil {
   313→		return err
   314→	}
   315→	// encode GasLimit
   316→	if err := rlp.EncodeInt(tx.GasLimit, w, b); err != nil {
   317→		return err
   318→	}
   319→	// encode To
   320→	if err := rlp.EncodeOptionalAddress(tx.To, w, b); err != nil {
   321→		return err
   322→	}
   323→	// encode Value
   324→	if err := rlp.EncodeUint256(tx.Value, w, b); err != nil {
   325→		return err
   326→	}
   327→	// encode Data
   328→	if err := rlp.EncodeString(tx.Data, w, b); err != nil {
   329→		return err
   330→	}
   331→	// prefix
   332→	if err := rlp.EncodeStructSizePrefix(accessListLen, w, b); err != nil {
   333→		return err
   334→	}
   335→	// encode AccessList
   336→	if err := encodeAccessList(tx.AccessList, w, b); err != nil {
   337→		return err
   338→	}
   339→	// prefix
   340→	if err := rlp.EncodeStructSizePrefix(authorizationsLen, w, b); err != nil {
   341→		return err
   342→	}
   343→	// encode Authorizations
   344→	if err := encodeAuthorizations(tx.Authorizations, w, b); err != nil {
   345→		return err
   346→	}
   347→	// encode V
   348→	if err := rlp.EncodeUint256(&tx.V, w, b); err != nil {
   349→		return err
   350→	}
   351→	// encode R
   352→	if err := rlp.EncodeUint256(&tx.R, w, b); err != nil {
   353→		return err
   354→	}
   355→	// encode S
   356→	if err := rlp.EncodeUint256(&tx.S, w, b); err != nil {
   357→		return err
   358→	}
   359→	return nil
   360→
   361→}
   362→
   363→// ParseDelegation tries to parse the address from a delegation slice.
   364→func ParseDelegation(code []byte) (common.Address, bool) {
   365→	if len(code) != DelegateDesignationCodeSize || !bytes.HasPrefix(code, params.DelegatedDesignationPrefix) {
   366→		return common.Address{}, false
   367→	}
   368→	var addr common.Address
   369→	copy(addr[:], code[len(params.DelegatedDesignationPrefix):])
   370→	return addr, true
   371→}
   372→
   373→// AddressToDelegation adds the delegation prefix to the specified address.
   374→func AddressToDelegation(addr common.Address) []byte {
   375→	return append(params.DelegatedDesignationPrefix, addr.Bytes()...)
   376→}
